#include <iostream>
#include <vector>
#include <string>
using namespace std;
void solve() {
    int n;
    string s;
    cin >> n >> s;
    vector<int> fixed;
    for (int j = 0; j < n; ++j) if (s[j] != 'F') fixed.push_back(j);
    int low = 0, high = 0, step = 1;
    if (fixed.empty()) {
        high = n - 1;
    } else {
        int freeEdges = fixed.front() + n - 1 - fixed.back();
        high = freeEdges;
        step = freeEdges ? 1 : 2;
        for (int j = 1; j < (int)fixed.size(); ++j) {
            int length = fixed[j] - fixed[j - 1];
            int different = s[fixed[j]] != s[fixed[j - 1]];
            low += (length - different) % 2;
            high += length - different;
        }
    }
    cout << (high - low) / step + 1 << '\n';
    for (int value = low; value <= high; value += step) cout << value << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve();
    return 0;
}
