#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;
void solve() {
    int tests;
    cin >> tests;
    while (tests--) {
        int n, commas, periods;
        cin >> n >> commas >> periods;
        vector<string> nouns, transitive, intransitive, conjunctions;
        for (int j = 0; j < n; ++j) {
            string word, type;
            cin >> word >> type;
            if (type == "noun") nouns.push_back(word);
            else if (type == "transitive-verb") transitive.push_back(word);
            else if (type == "intransitive-verb") intransitive.push_back(word);
            else conjunctions.push_back(word);
        }
        int capacity = min(periods + (int)conjunctions.size(), 2 * periods);
        int best = 0, chosenX = 0, chosenY = 0, chosenJoins = 0, chosenExtra = 0;
        for (int y = 0; y <= (int)transitive.size() && 2 * y <= (int)nouns.size() && y <= capacity; ++y) {
            int x = min((int)intransitive.size(), min((int)nouns.size() - 2 * y, capacity - y));
            int joins = min((int)conjunctions.size(), (x + y) / 2);
            int extra = y ? min(commas, (int)nouns.size() - x - 2 * y) : 0;
            int value = 2 * x + 3 * y + joins + extra;
            if (value > best) {
                best = value; chosenX = x; chosenY = y;
                chosenJoins = joins; chosenExtra = extra;
            }
        }
        vector<string> sentences;
        int ni = 0;
        for (int j = 0; j < chosenX; ++j) {
            sentences.push_back(nouns[ni++] + " " + intransitive[j]);
        }
        for (int j = 0; j < chosenY; ++j) {
            string subject = nouns[ni++];
            string object = nouns[ni++];
            string sentence = subject + " " + transitive[j] + " " + object;
            if (j == 0) for (int k = 0; k < chosenExtra; ++k) sentence += ", " + nouns[ni++];
            sentences.push_back(sentence);
        }
        string output;
        int at = 0;
        for (int j = 0; j < chosenJoins; ++j) {
            if (!output.empty()) output += " ";
            output += sentences[at] + " " + conjunctions[j] + " " + sentences[at + 1] + ".";
            at += 2;
        }
        while (at < (int)sentences.size()) {
            if (!output.empty()) output += " ";
            output += sentences[at++] + ".";
        }
        cout << best << '\n' << output << '\n';
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve();
    return 0;
}
