#include <iostream>
#include <vector>
using namespace std;
void solve() {
    int n, k;
    long long minutes;
    cin >> n >> k >> minutes;
    vector<int> active(k), next(n), answer(n);
    for (int &position : active) cin >> position;
    for (int j = 0; j < n; ++j) next[j] = (j + n - 1) % n;
    for (int j = 0; j < k; ++j) next[active[j]] = (active[(j + 1) % k] + n - 1) % n;
    vector<bool> seen(n, false);
    for (int start = 0; start < n; ++start) {
        if (seen[start]) continue;
        vector<int> cycle;
        int at = start;
        do {
            seen[at] = true;
            cycle.push_back(at);
            at = next[at];
        } while (at != start);
        int shift = (int)(minutes % cycle.size());
        for (int j = 0; j < (int)cycle.size(); ++j) {
            int finalRelative = cycle[(j + shift) % cycle.size()];
            int finalPosition = (int)((finalRelative + minutes) % n);
            answer[finalPosition] = cycle[j];
        }
    }
    for (int j = 0; j < n; ++j) cout << (j ? " " : "") << answer[j];
    cout << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve();
    return 0;
}
